def transform(grid):
    # Extend every diagonal run of at least two same-colored cells at both open ends.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg: continue
            for dr, dc in ((1,1),(1,-1)):
                if not (0 <= r-dr < h and 0 <= c-dc < w and grid[r-dr][c-dc] == color): continue
                # Find end of this consecutive same-color diagonal segment.
                rr, cc = r, c
                while 0 <= rr+dr < h and 0 <= cc+dc < w and grid[rr+dr][cc+dc] == color:
                    rr += dr; cc += dc
                for sign in (-1, 1):
                    ar, ac = (r-dr, c-dc) if sign == -1 else (rr+dr, cc+dc)
                    sr, sc = (-dr, -dc) if sign == -1 else (dr, dc)
                    while 0 <= ar < h and 0 <= ac < w:
                        if out[ar][ac] == bg: out[ar][ac] = color
                        ar += sr; ac += sc
    return out", "exit_code": 0, "error": null}

